{"cards": [{"node_code": "N_0f8aae0be8062fad", "definition": "研究铁路线路结构（路基、轨道、道岔等）在静力、动力及环境荷载作用下的承载能力、应力分布、变形特性及破坏机理的力学理论。", "boundary": "本节点聚焦于线路结构的“强度”与“承载”理论，区别于“稳定性”（侧重失稳与平衡）和“振动”（侧重动态响应）。边界在于区分“强度计算”与“构造设计”（具体尺寸归入线路构造）、“强度理论”与“材料力学”（通用材料属性归入材料科学，此处侧重线路结构整体）。若涉及疲劳寿命，侧重机理归本节点，侧重试验数据归入线路试验。", "includes": ["路基与轨道结构的静力强度分析与承载能力计算", "线路结构在动荷载作用下的应力、应变及疲劳损伤理论", "线路结构破坏模式、安全系数及极限状态理论"], "excludes": ["线路结构的整体失稳与平衡问题（归入线路稳定性）", "线路结构的动态响应与频率特性（归入线路振动）", "具体的线路结构设计图纸与规范应用（归入线路规划、勘测与设计）"], "sibling_distinctions": [{"other_code": "N_93dcd02167ef4e68", "rule": "区分依据为失效模式：线路强度关注材料或结构的承载极限与破坏；线路稳定性关注结构在荷载下的平衡状态保持与失稳（如路基边坡滑移、轨道框架失稳）。"}, {"other_code": "N_0a521f4572740011", "rule": "区分依据为时间特性：线路强度侧重静态或准静态下的承载能力；线路振动侧重动态荷载下的频率、振幅及共振特性。"}], "cross_boundary_rule": "若内容涉及“强度-稳定性耦合”或“动力强度”，若侧重静态承载极限，主挂载本节点；若侧重动态响应或失稳机理，主挂载对应节点。"}, {"node_code": "N_93dcd02167ef4e68", "definition": "研究铁路线路结构（路基、轨道、边坡等）在荷载与环境作用下保持平衡状态、抵抗失稳破坏的力学理论，涵盖边坡稳定、轨道框架稳定等。", "boundary": "本节点聚焦于线路结构的“稳定性”与“平衡”理论，区别于“强度”（侧重材料破坏）和“振动”（侧重动态响应）。边界在于区分“稳定性分析”与“强度计算”（强度关注应力是否超过极限，稳定性关注平衡是否丧失）、“稳定性”与“耐久性”（耐久性归入养护或材料）。若涉及路基边坡，侧重滑移面与抗滑力归本节点，侧重土体强度参数归入线路强度或材料。", "includes": ["路基边坡、路堤及路堑的稳定性分析与抗滑理论", "轨道结构框架的几何稳定性与失稳机理", "线路结构在长期荷载或环境作用下的蠕变与长期稳定性理论"], "excludes": ["线路结构的材料强度与承载能力计算（归入线路强度）", "线路结构的动态振动响应（归入线路振动）", "具体的边坡防护工程措施与施工（归入线路施工或线路构造）"], "sibling_distinctions": [{"other_code": "N_0f8aae0be8062fad", "rule": "区分依据为失效模式：线路稳定性关注结构整体或局部的平衡丧失（如滑移、倾覆）；线路强度关注材料或构件的应力超过极限导致的破坏。"}, {"other_code": "N_0a521f4572740011", "rule": "区分依据为荷载特性：线路稳定性侧重静态或准静态下的平衡保持；线路振动侧重动态荷载下的运动特性。"}], "cross_boundary_rule": "若内容涉及“动力稳定性”或“强度-稳定耦合”，若侧重静态平衡与失稳机理，主挂载本节点；若侧重动态响应或材料破坏，主挂载对应节点。"}, {"node_code": "N_0a521f4572740011", "definition": "研究铁路线路结构在机车车辆动荷载、风荷载等动态激励下的振动特性、动力响应、共振机理及减振降噪理论的力学体系。", "boundary": "本节点聚焦于线路结构的“振动”与“动态响应”理论，区别于“强度”（静态承载）和“稳定性”（平衡保持）。边界在于区分“振动理论”与“疲劳强度”（疲劳归入强度，振动归入动态响应）、“振动”与“噪声”（噪声是振动的声学表现，若侧重声学归入噪声控制，侧重结构振动归本节点）。若涉及轨道板振动，侧重结构动力学归本节点，侧重材料阻尼归入材料。", "includes": ["轨道结构、路基及桥梁的振动特性与频率分析", "机车车辆动荷载作用下的线路动力响应与共振理论", "线路振动减振、隔振及振动控制理论"], "excludes": ["线路结构的静态强度与承载能力（归入线路强度）", "线路结构的静态稳定性与失稳（归入线路稳定性）", "具体的减振装置构造与施工（归入线路构造或施工）"], "sibling_distinctions": [{"other_code": "N_0f8aae0be8062fad", "rule": "区分依据为荷载特性：线路振动关注动态荷载下的运动响应与频率特性；线路强度关注静态或准静态下的应力与破坏。"}, {"other_code": "N_93dcd02167ef4e68", "rule": "区分依据为失效模式：线路振动关注动态平衡与共振；线路稳定性关注静态平衡丧失与失稳。"}], "cross_boundary_rule": "若内容涉及“动力强度”或“振动疲劳”，若侧重动态响应与频率特性，主挂载本节点；若侧重疲劳损伤累积，主挂载线路强度。"}]}
